
/*
    PROJETO CRUD E ESTOQUE EM JAVASCRIPT

        CRUD:
            C - Create (Cadastrar)
                R - Read (Listar)
                    U - Update (Atualizar)
                        D - Delete (Excluir)
                        */

                        // 1. Criação da lista de produtos

                        let produtos = [
                            {
                                    codigo: 1,
                                            descricao: "Teclado",
                                                    quantidade: 10,
                                                            valor: 150.00
                                                                },
                                                                    {
                                                                            codigo: 2,
                                                                                    descricao: "Mouse",
                                                                                            quantidade: 20,
                                                                                                    valor: 80.00
                                                                                                        },
                                                                                                            {
                                                                                                                    codigo: 3,
                                                                                                                            descricao: "Monitor",
                                                                                                                                    quantidade: 5,
                                                                                                                                            valor: 750.00
                                                                                                                                                }
                                                                                                                                                ];

                                                                                                                                                // 2. Geração automática do código

                                                                                                                                                let proximoCodigo = 4;


                                                                                                                                                // 3. Mapeamento dos elementos do HTML

                                                                                                                                                const formProduto = document.getElementById("formProduto");

                                                                                                                                                const descricaoInput = document.getElementById("descricao");
                                                                                                                                                const quantidadeInput = document.getElementById("quantidade");
                                                                                                                                                const valorInput = document.getElementById("valor");

                                                                                                                                                const listaProdutos = document.getElementById("listaProdutos");

                                                                                                                                                const mensagem = document.getElementById("mensagem");

                                                                                                                                                const totalProdutos = document.getElementById("totalProdutos");
                                                                                                                                                const valorEstoque = document.getElementById("valorEstoque");


                                                                                                                                                // 4. Função para validar produto

                                                                                                                                                function validarProduto(descricao, quantidade, valor) {

                                                                                                                                                    if (descricao.trim() === "") {
                                                                                                                                                            return "A descrição do produto é obrigatória.";
                                                                                                                                                                }

                                                                                                                                                                    if (!Number.isInteger(quantidade) || quantidade <= 0) {
                                                                                                                                                                            return "A quantidade deve ser um número inteiro positivo.";
                                                                                                                                                                                }

                                                                                                                                                                                    if (!Number.isFinite(valor) || valor <= 0) {
                                                                                                                                                                                            return "O valor deve ser maior que zero.";
                                                                                                                                                                                                }

                                                                                                                                                                                                    return null;
                                                                                                                                                                                                    }


                                                                                                                                                                                                    // 5. Função para cadastrar produto

                                                                                                                                                                                                    function cadastrarProduto(event) {

                                                                                                                                                                                                        event.preventDefault();

                                                                                                                                                                                                            const descricao = descricaoInput.value.trim();

                                                                                                                                                                                                                const quantidade = Number(quantidadeInput.value);

                                                                                                                                                                                                                    const valor = Number(valorInput.value);

                                                                                                                                                                                                                        // Validação dos dados

                                                                                                                                                                                                                            const erro = validarProduto(
                                                                                                                                                                                                                                    descricao,
                                                                                                                                                                                                                                            quantidade,
                                                                                                                                                                                                                                                    valor
                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                            if (erro) {
                                                                                                                                                                                                                                                                    mostrarMensagem(erro, "erro");
                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                    // Criação do objeto produto

                                                                                                                                                                                                                                                                                        const produto = {
                                                                                                                                                                                                                                                                                                codigo: proximoCodigo,
                                                                                                                                                                                                                                                                                                        descricao: descricao,
                                                                                                                                                                                                                                                                                                                quantidade: quantidade,
                                                                                                                                                                                                                                                                                                                        valor: valor
                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                // Adicionando produto ao array

                                                                                                                                                                                                                                                                                                                                    produtos.push(produto);

                                                                                                                                                                                                                                                                                                                                        proximoCodigo++;

                                                                                                                                                                                                                                                                                                                                            // Atualização da listagem

                                                                                                                                                                                                                                                                                                                                                renderizarProdutos();

                                                                                                                                                                                                                                                                                                                                                    // Limpar formulário

                                                                                                                                                                                                                                                                                                                                                        formProduto.reset();

                                                                                                                                                                                                                                                                                                                                                            mostrarMensagem(
                                                                                                                                                                                                                                                                                                                                                                    "Produto cadastrado com sucesso!",
                                                                                                                                                                                                                                                                                                                                                                            "sucesso"
                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                // 6. Função para listar produtos

                                                                                                                                                                                                                                                                                                                                                                                function renderizarProdutos() {

                                                                                                                                                                                                                                                                                                                                                                                    listaProdutos.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                        produtos.forEach(function(produto) {

                                                                                                                                                                                                                                                                                                                                                                                                const linha = document.createElement("tr");

                                                                                                                                                                                                                                                                                                                                                                                                        const valorTotal = produto.quantidade * produto.valor;

                                                                                                                                                                                                                                                                                                                                                                                                                linha.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                            <td>${produto.codigo}</td>

                                                                                                                                                                                                                                                                                                                                                                                                                                        <td>${produto.descricao}</td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                    <td>${produto.quantidade}</td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                <td>${formatarMoeda(produto.valor)}</td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <td>${formatarMoeda(valorTotal)}</td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            class="btn-editar"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onclick="atualizarValor(${produto.codigo})"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Alterar Valor
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        class="btn-estoque"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onclick="atualizarQuantidade(${produto.codigo})"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Adicionar Estoque
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listaProdutos.appendChild(linha);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Atualização dos indicadores

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        totalProdutos.textContent = produtos.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const total = produtos.reduce(function(soma, produto) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return soma + (produto.quantidade * produto.valor);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }, 0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            valorEstoque.textContent = formatarMoeda(total);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 7. Função para atualizar o valor do produto

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function atualizarValor(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Busca do produto com find

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const produto = produtos.find(function(item) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return item.codigo === codigo;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Tratamento de produto não encontrado

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!produto) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarMensagem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Produto não encontrado.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "erro"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const novoValor = prompt(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `Digite o novo valor para ${produto.descricao}:`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (novoValor === null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const valor = Number(novoValor);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!Number.isFinite(valor) || valor <= 0) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarMensagem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Informe um valor válido maior que zero.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "erro"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            produto.valor = valor;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                renderizarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Valor atualizado com sucesso!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "sucesso"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 8. Função para atualizar a quantidade

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function atualizarQuantidade(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const produto = produtos.find(function(item) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return item.codigo === codigo;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!produto) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Produto não encontrado.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "erro"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const quantidadeAdicional = prompt(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `Quantas unidades deseja adicionar ao estoque de ${produto.descricao}?`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (quantidadeAdicional === null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const quantidade = Number(quantidadeAdicional);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!Number.isInteger(quantidade) || quantidade <= 0) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarMensagem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Informe uma quantidade inteira positiva.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "erro"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Soma da quantidade ao estoque atual

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    produto.quantidade += quantidade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        renderizarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarMensagem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Estoque atualizado com sucesso!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "sucesso"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 9. Função para formatar valores monetários

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function formatarMoeda(valor) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return valor.toLocaleString("pt-BR", {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style: "currency",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    currency: "BRL"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 10. Função para exibir mensagens

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function mostrarMensagem(texto, tipo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mensagem.textContent = texto;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mensagem.className = tipo;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 11. Evento de cadastro

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                formProduto.addEventListener(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "submit",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cadastrarProduto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 12. Chamada inicial da função renderizar

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        renderizarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        